contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    function run(address target, bytes calldata data, uint sendAmount, bool callWithdraw, bool callCommand) public payable {
        // we will send some Ether to C to allow withdraw/Command value transfers
        // ensure this contract has enough balance to forward sendAmount when needed
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
            // fund c by using multiplicate in a way that will transfer ether out if condition met is unsafe;
            // instead, just send ether to c using payable fallback via Command if we are Owner
        }

        // read initial values
        address owner = c.Owner();
        uint beforeBal = address(c).balance;

        // If this contract is the owner (it is NOT, because C was deployed externally and Owner==deployer),
        // then calls would succeed. We want to observe both owner and non-owner behavior depending on owner value.
        // The spec: only Owner can successfully call withdraw or Command; non-owner must revert.

        bool withdrewReverted = false;
        bool commandReverted = false;

        // Try withdraw (may revert)
        try c.withdraw{value: 0}() {
            withdrewReverted = false;
        } catch {
            withdrewReverted = true;
        }

        // Try Command forwarding some value
        if (sendAmount > 0) {
            // ensure we have funds to send
            require(address(this).balance >= sendAmount);
        }
        try c.Command{value: sendAmount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        uint afterBal = address(c).balance;

        // General rule asserted:
        // - If msg.sender (this test contract) is the Owner of c, then withdraw must not revert and afterBal==0 (all funds transferred out).
        // - If msg.sender is not Owner, then withdraw must revert.
        // - Similarly for Command: if msg.sender is Owner then Command must not revert; if not Owner then it must revert.
        // We express this as a single assert combining both actions. Note: withdraw was called with value 0 above.
        bool amOwner = (address(this) == owner);

        assert(
            // withdraw behavior
            ((amOwner && !withdrewReverted && afterBal == 0) || (!amOwner && withdrewReverted))
            // and Command behavior
            && ((amOwner && !commandReverted) || (!amOwner && commandReverted))
        );
    }

    // allow receiving ether for forwarding in the test
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function
    // params: recipient address and amount to send with multiplicate
    function run(address adr, uint sendAmount) public payable {
        // ensure this test contract has enough balance to forward sendAmount when calling multiplicate
        if (sendAmount > 0) {
            require(address(this).balance >= sendAmount);
        }

        // observe balance before
        uint before = address(c).balance;

        // attempt the multiplicate call, catching reverts
        bool reverted;
        try c.multiplicate{value: sendAmount}(adr) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint after = address(c).balance;

        // General rule:
        // - multiplicate never increases the contract balance (after <= before + sendAmount is always true,
        //   but stronger: it never increases relative to before unless the call reverted; here we assert it never increases at all)
        // - if sendAmount >= before and the call succeeded (not reverted), then c.balance becomes 0 (funds were forwarded out)
        // This captures that multiplicate either forwards out the whole balance+msg.value when condition met, or does nothing (or reverts).
        assert(
            // never increases c's balance
            after <= before
            // if condition met and did not revert, then balance is zero
            && (!(sendAmount >= before) || reverted || after == 0)
        );
    }

    // allow receiving ether for test funding
    receive() external payable {}
}

