contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // run tests varying who the Owner is by using c.Owner() (deployed with this contract as creator)
    // params: amount to send with calls, target address and calldata for Command, and recipient for multiplicate
    function run(uint amount, address target, bytes calldata data, address payable multRecipient) public payable {
        require(address(this).balance >= amount);

        // Read current Owner and c balance before any actions
        address ownerBefore = c.Owner();
        uint balBefore = address(c).balance;

        // Try withdraw and record whether it reverted
        bool withdrawReverted;
        try c.withdraw{value: 0}() {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Try Command with provided value and data
        bool commandReverted;
        try c.Command{value: amount}(target, data) {
            commandReverted = false;
        } catch {
            commandReverted = true;
        }

        // If this test contract is the Owner, withdraw must succeed and clear c's balance.
        // Otherwise, withdraw must have reverted. Also, only Owner may call Command successfully.
        // Express the general rule as a single assert combining these observations.
        if (ownerBefore == address(this)) {
            // when Owner is this contract: withdraw should not revert and c balance becomes 0
            assert(!withdrawReverted && address(c).balance == 0);
        } else {
            // when Owner is not this contract: both withdraw and Command must revert
            assert(withdrawReverted && commandReverted);
        }
    }

    receive() external payable {}
}

