contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // We will test behavior of Command: only Owner can call it; it forwards msg.value to the target
    // Public test entry point. We take target address, calldata, and an amount to forward.
    function run(address target, bytes calldata data, uint amount) public payable {
        require(address(this).balance >= amount);

        // Read owner and balance before the call
        address ownerBefore = c.Owner();
        uint balanceBefore = address(c).balance;

        bool didRevert;
        // Call Command as this contract, forwarding `amount` wei
        try c.Command{value: amount}(target, data) {
            didRevert = false;
        } catch {
            didRevert = true;
        }

        address ownerAfter = c.Owner();
        uint balanceAfter = address(c).balance;

        // General rule to assert:
        // - Owner must not change due to Command invocation.
        // - If this contract was Owner before the call, then the difference in c's balance is at most `amount` (it cannot increase by more than amount),
        //   and it cannot decrease by more than balanceBefore + amount (i.e., balanceAfter >= 0 implicitly true). More usefully: if the call succeeded (didRevert==false)
        //   then c's balance decreased by exactly `amount` (Command forwards msg.value to target via low-level call which either consumes the value
        //   or reverts; but since we observed success, the funds must have left c). If it reverted, balanceAfter == balanceBefore.
        // We encode this as a single assert combining these observations.

        assert(
            // Owner invariant: Command does not change Owner
            ownerBefore == ownerAfter
            && (
                // If call reverted -> balance unchanged
                (didRevert && balanceAfter == balanceBefore)
                ||
                // If call succeeded and this contract was Owner, c must have forwarded the exact amount -> balanceAfter == balanceBefore - amount
                (!didRevert && ownerBefore == address(this) && balanceAfter + amount == balanceBefore)
                ||
                // If call succeeded but this contract was not Owner, the call would have reverted due to require; thus this branch should be unreachable
                // so we demand that if call succeeded then ownerBefore == this
                (!didRevert && ownerBefore == address(this))
            )
        );
    }

    receive() external payable {}
}
